 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);ap.add_argument('--commit',required=True);a=ap.parse_args();r=a.root;d=json.loads((r/'results/run_provenance_v86.json').read_text());d['schema']='run_provenance_v87';d['created_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();d['github_main_commit']=a.commit;d['source_alignment']='results/main_nersc_source_alignment_v45.json';d['source_alignment_sha256']=sha(r/'results/main_nersc_source_alignment_v45.json');d['stage_progress']='results/stage_progress_v31.json';d['stage_progress_sha256']=sha(r/'results/stage_progress_v31.json');d['stage8_holdout_report']='results/stage8_holdout_validation_report_v12.json';d['stage8_holdout_report_sha256']=sha(r/'results/stage8_holdout_validation_report_v12.json');d['bphi_scale_window_scan']='results/bphi_response_scale_window_scan_v1.json';d['bphi_scale_window_scan_sha256']=sha(r/'results/bphi_response_scale_window_scan_v1.json');d['batch_outputs']['source_alignment_v45']='results/main_nersc_source_alignment_v45.json';d['batch_outputs']['stage_progress_v31']='results/stage_progress_v31.json';d['batch_outputs']['stage8_holdout_report_v12']='results/stage8_holdout_validation_report_v12.json';d['batch_outputs']['bphi_scale_window_scan']='results/bphi_response_scale_window_scan_v1.json';d['status']='PARTIAL';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'status':d['status'],'commit':a.commit}))
